fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let r: i32 = if w < h { w / 3 } else { h / 3 };
    host::display::clear(0x000000);
    host::display::fill_rect(cx - 8, cy - 8, 16, 16, 0xffcc00);
    let a: i32 = (t / 2) & 31;
    let px: i32 = cx + tab[a] * r / 127;
    let py: i32 = cy + tab[(a + 8) & 31] * r / 127;
    host::display::fill_rect(px - 5, py - 5, 10, 10, 0x4090ff);
    let m: i32 = (t * 3 / 2) & 31;
    let mx: i32 = px + tab[m] * 18 / 127;
    let my: i32 = py + tab[(m + 8) & 31] * 18 / 127;
    host::display::fill_rect(mx - 2, my - 2, 4, 4, 0xc0c0c0);
    host::display::present();
}
